import { action, api, apiNamespace, app, page, query, route } from "@wasp.sh/spec";

import { LoginPage, SignupPage } from "./src/pages/auth" with { type: "ref" };
import { DashboardPage } from "./src/pages/DashboardPage" with { type: "ref" };
import { LogsPage } from "./src/pages/LogsPage" with { type: "ref" };
import { SharePage } from "./src/pages/SharePage" with { type: "ref" };

import {
  getAccessLogs,
  getFolderContents,
  getShareLinkInfo,
} from "./src/queries" with { type: "ref" };
import {
  createFolder,
  createShareLink,
  unlockShareLink,
} from "./src/actions" with { type: "ref" };
import {
  configureUploadMiddleware,
  downloadFile,
  enableApiCors,
  uploadFile,
} from "./src/apis" with { type: "ref" };

export default app({
  name: "app",
  wasp: { version: "^0.25.0" },
  title: "app",
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthFailedRedirectTo: "/login",
  },
  spec: [
    // Auth pages
    route("SignupRoute", "/signup", page(SignupPage)),
    route("LoginRoute", "/login", page(LoginPage)),

    // Dashboard pages
    route("RootRoute", "/", page(DashboardPage, { authRequired: true })),
    route(
      "FolderRoute",
      "/folder/:folderId",
      page(DashboardPage, { authRequired: true }),
    ),

    // Access logs page
    route("LogsRoute", "/logs", page(LogsPage, { authRequired: true })),

    // Public share page
    route("ShareRoute", "/share/:linkId", page(SharePage)),

    // Queries
    query(getFolderContents, { entities: ["Folder", "File"] }),
    query(getAccessLogs, { entities: ["AccessLog"] }),
    query(getShareLinkInfo, { entities: ["ShareLink", "File"], auth: false }),

    // Actions
    action(createFolder, { entities: ["Folder"] }),
    action(createShareLink, { entities: ["File", "ShareLink"] }),
    action(unlockShareLink, { entities: ["ShareLink"], auth: false }),

    // File upload API (multipart, so it can't be a normal Action)
    apiNamespace("/api/upload", { middlewareConfigFn: configureUploadMiddleware }),
    api("POST", "/api/upload", uploadFile, { entities: ["File", "Folder"] }),

    // Public file download API
    apiNamespace("/api/download", { middlewareConfigFn: enableApiCors }),
    api("GET", "/api/download/:linkId", downloadFile, {
      entities: ["ShareLink", "File", "AccessLog"],
      auth: false,
    }),
  ],
});

import crypto from "node:crypto";

/**
 * Hashes a plain-text password using scrypt with a random salt.
 * The result is stored as `${salt}:${hash}` (both hex-encoded).
 */
export function hashPassword(password: string): string {
  const salt = crypto.randomBytes(16).toString("hex");
  const derivedKey = crypto.scryptSync(password, salt, 64);
  return `${salt}:${derivedKey.toString("hex")}`;
}

/**
 * Verifies a plain-text password against a hash produced by `hashPassword`.
 */
export function verifyPassword(password: string, stored: string): boolean {
  const [salt, hash] = stored.split(":");
  if (!salt || !hash) {
    return false;
  }

  const hashBuffer = Buffer.from(hash, "hex");
  const derivedKey = crypto.scryptSync(password, salt, 64);

  if (derivedKey.length !== hashBuffer.length) {
    return false;
  }

  return crypto.timingSafeEqual(derivedKey, hashBuffer);
}

import { HttpError } from "wasp/server";
import type {
  AccessLog,
  File as FileEntity,
  Folder,
} from "wasp/entities";
import type {
  GetAccessLogs,
  GetFolderContents,
  GetShareLinkInfo,
} from "wasp/server/operations";

type Breadcrumb = {
  id: number;
  name: string;
};

type FolderContents = {
  currentFolder: Folder | null;
  breadcrumbs: Breadcrumb[];
  folders: Folder[];
  files: FileEntity[];
};

export const getFolderContents: GetFolderContents<
  { folderId?: number },
  FolderContents
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "You must be logged in");
  }

  const userId = context.user.id;
  let currentFolder: Folder | null = null;

  if (args.folderId !== undefined && args.folderId !== null) {
    currentFolder = await context.entities.Folder.findUnique({
      where: { id: args.folderId },
    });

    if (!currentFolder || currentFolder.userId !== userId) {
      throw new HttpError(404, "Folder not found");
    }
  }

  const breadcrumbs: Breadcrumb[] = [];
  let cursor: Folder | null = currentFolder;
  while (cursor) {
    breadcrumbs.unshift({ id: cursor.id, name: cursor.name });
    if (cursor.parentId === null || cursor.parentId === undefined) {
      cursor = null;
    } else {
      cursor = await context.entities.Folder.findUnique({
        where: { id: cursor.parentId },
      });
    }
  }

  const folders = await context.entities.Folder.findMany({
    where: {
      userId,
      parentId: currentFolder ? currentFolder.id : null,
    },
    orderBy: { name: "asc" },
  });

  const files = await context.entities.File.findMany({
    where: {
      userId,
      folderId: currentFolder ? currentFolder.id : null,
    },
    orderBy: { name: "asc" },
  });

  return { currentFolder, breadcrumbs, folders, files };
};

export const getAccessLogs: GetAccessLogs<void, AccessLog[]> = async (
  _args,
  context,
) => {
  if (!context.user) {
    throw new HttpError(401, "You must be logged in");
  }

  return context.entities.AccessLog.findMany({
    where: { ownerId: context.user.id },
    orderBy: { accessedAt: "desc" },
  });
};

type ShareLinkInfo = {
  fileName: string;
  requiresPassword: boolean;
  isExpired: boolean;
};

export const getShareLinkInfo: GetShareLinkInfo<
  { linkId: string },
  ShareLinkInfo
> = async (args, context) => {
  const shareLink = await context.entities.ShareLink.findUnique({
    where: { id: args.linkId },
    include: { file: true },
  });

  if (!shareLink) {
    throw new HttpError(404, "This share link does not exist");
  }

  const isExpired = shareLink.expiresAt
    ? shareLink.expiresAt.getTime() < Date.now()
    : false;

  return {
    fileName: shareLink.file.name,
    requiresPassword: !!shareLink.passwordHash,
    isExpired,
  };
};

import { HttpError } from "wasp/server";
import type { Folder, ShareLink } from "wasp/entities";
import type {
  CreateFolder,
  CreateShareLink,
  UnlockShareLink,
} from "wasp/server/operations";
import { hashPassword, verifyPassword } from "./server/crypto";

export const createFolder: CreateFolder<
  { name: string; parentId?: number },
  Folder
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "You must be logged in");
  }

  const name = args.name?.trim();
  if (!name) {
    throw new HttpError(400, "Folder name is required");
  }

  if (args.parentId !== undefined && args.parentId !== null) {
    const parent = await context.entities.Folder.findUnique({
      where: { id: args.parentId },
    });
    if (!parent || parent.userId !== context.user.id) {
      throw new HttpError(404, "Parent folder not found");
    }
  }

  return context.entities.Folder.create({
    data: {
      name,
      parentId: args.parentId ?? null,
      userId: context.user.id,
    },
  });
};

export const createShareLink: CreateShareLink<
  { fileId: number; password?: string; expiresInMinutes?: number },
  ShareLink
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "You must be logged in");
  }

  const file = await context.entities.File.findUnique({
    where: { id: args.fileId },
  });

  if (!file || file.userId !== context.user.id) {
    throw new HttpError(404, "File not found");
  }

  const passwordHash = args.password ? hashPassword(args.password) : null;
  const expiresAt =
    args.expiresInMinutes && args.expiresInMinutes > 0
      ? new Date(Date.now() + args.expiresInMinutes * 60 * 1000)
      : null;

  return context.entities.ShareLink.create({
    data: {
      fileId: file.id,
      userId: context.user.id,
      passwordHash,
      expiresAt,
    },
  });
};

export const unlockShareLink: UnlockShareLink<
  { linkId: string; password: string },
  { success: boolean }
> = async (args, context) => {
  const shareLink = await context.entities.ShareLink.findUnique({
    where: { id: args.linkId },
  });

  if (!shareLink) {
    throw new HttpError(404, "This share link does not exist");
  }

  if (shareLink.expiresAt && shareLink.expiresAt.getTime() < Date.now()) {
    throw new HttpError(410, "This share link has expired");
  }

  if (!shareLink.passwordHash) {
    return { success: true };
  }

  const isValid = verifyPassword(args.password ?? "", shareLink.passwordHash);
  if (!isValid) {
    throw new HttpError(401, "Incorrect password");
  }

  return { success: true };
};

import fs from "node:fs";
import path from "node:path";
import multer from "multer";
import { HttpError } from "wasp/server";
import type { MiddlewareConfigFn } from "wasp/server";
import type { DownloadFile, UploadFile } from "wasp/server/api";
import { verifyPassword } from "./server/crypto";

export const UPLOADS_DIR = "/home/user/app/uploads/";

// Make sure the uploads directory exists before Multer tries to write to it.
fs.mkdirSync(UPLOADS_DIR, { recursive: true });

const upload = multer({ dest: UPLOADS_DIR });

export const configureUploadMiddleware: MiddlewareConfigFn = (config) => {
  config.set("multer", upload.single("file"));
  return config;
};

// Returning the (already CORS-enabled) default middleware config makes sure
// this API namespace can be called from the client with `wasp/client/api`.
export const enableApiCors: MiddlewareConfigFn = (config) => {
  return config;
};

export const uploadFile: UploadFile = async (req, res, context) => {
  if (!context.user) {
    res.status(401).json({ error: "You must be logged in" });
    return;
  }

  const uploadedFile = req.file;
  if (!uploadedFile) {
    res.status(400).json({ error: "No file provided" });
    return;
  }

  const folderIdRaw = req.body?.folderId;
  let folderId: number | null = null;
  if (
    folderIdRaw !== undefined &&
    folderIdRaw !== null &&
    folderIdRaw !== "" &&
    folderIdRaw !== "null" &&
    folderIdRaw !== "undefined"
  ) {
    folderId = parseInt(String(folderIdRaw), 10);
  }

  if (folderId !== null) {
    const folder = await context.entities.Folder.findUnique({
      where: { id: folderId },
    });
    if (!folder || folder.userId !== context.user.id) {
      res.status(404).json({ error: "Folder not found" });
      return;
    }
  }

  const originalName =
    (req.body?.name as string | undefined) || uploadedFile.originalname;

  const file = await context.entities.File.create({
    data: {
      name: originalName,
      storedName: uploadedFile.filename,
      size: uploadedFile.size,
      mimeType: uploadedFile.mimetype || "application/octet-stream",
      folderId,
      userId: context.user.id,
    },
  });

  res.json({ file });
};

export const downloadFile: DownloadFile = async (req, res, context) => {
  const { linkId } = req.params;
  const passwordParam =
    typeof req.query.password === "string" ? req.query.password : undefined;

  const shareLink = await context.entities.ShareLink.findUnique({
    where: { id: linkId },
  });

  if (!shareLink) {
    res.status(404).json({ error: "This share link does not exist" });
    return;
  }

  if (shareLink.expiresAt && shareLink.expiresAt.getTime() < Date.now()) {
    res.status(410).json({ error: "This share link has expired" });
    return;
  }

  if (shareLink.passwordHash) {
    if (
      !passwordParam ||
      !verifyPassword(passwordParam, shareLink.passwordHash)
    ) {
      res.status(401).json({ error: "Incorrect or missing password" });
      return;
    }
  }

  const file = await context.entities.File.findUnique({
    where: { id: shareLink.fileId },
  });

  if (!file) {
    res.status(404).json({ error: "File not found" });
    return;
  }

  const filePath = path.join(UPLOADS_DIR, file.storedName);
  if (!fs.existsSync(filePath)) {
    res.status(404).json({ error: "File is missing from storage" });
    return;
  }

  const forwardedFor = req.headers["x-forwarded-for"];
  const ipAddress =
    (typeof forwardedFor === "string"
      ? forwardedFor.split(",")[0]?.trim()
      : undefined) ||
    req.socket.remoteAddress ||
    "unknown";
  const userAgent = req.get("user-agent") || "unknown";

  await context.entities.AccessLog.create({
    data: {
      shareLinkId: shareLink.id,
      fileId: file.id,
      fileName: file.name,
      ownerId: shareLink.userId,
      ipAddress,
      userAgent,
    },
  });

  res.setHeader(
    "Content-Disposition",
    `attachment; filename="${encodeURIComponent(file.name)}"`,
  );
  res.setHeader("Content-Type", file.mimeType);
  fs.createReadStream(filePath).pipe(res);
};

// Avoid unused-import lint noise if HttpError isn't used directly above.
void HttpError;

